// Подготовка данных для запроса метрик
const test = $input.item.json;

let objectIds = [];
let level = 'ad';

if (test.test_category === 'creative' && test.facebook_ad_ids) {
  objectIds = test.facebook_ad_ids;
  level = 'ad';
} else if (test.test_category === 'audience' && test.facebook_adset_ids) {
  objectIds = test.facebook_adset_ids;
  level = 'adset';
}

return {
  test_id: test.id,
  test_name: test.name,
  test_category: test.test_category,
  object_a_id: objectIds[0] || null,
  object_b_id: objectIds[1] || null,
  level: level,
  auto_winner_threshold: test.auto_winner_threshold || 95,
  min_sample_size: test.min_sample_size || 1000
};

// Объединяем метрики A и B и рассчитываем confidence
const testData = $('📊 Подготовка данных').first().json;
const metricsA = $('📈 Метрики Variant A').first().json;
const metricsB = $('📈 Метрики Variant B').first().json;

// Парсим метрики
function parseMetrics(data) {
  const insights = data?.data?.[0] || {};
  const spend = parseFloat(insights.spend || 0);
  const impressions = parseInt(insights.impressions || 0);
  const clicks = parseInt(insights.clicks || 0);

  // Находим лиды в actions
  let leads = 0;
  if (insights.actions) {
    const leadAction = insights.actions.find(a => 
      a.action_type === 'lead' || 
      a.action_type === 'onsite_conversion.lead_grouped' ||
      a.action_type === 'offsite_conversion.fb_pixel_lead'
    );
    leads = parseInt(leadAction?.value || 0);
  }

  const cpl = leads > 0 ? spend / leads : null;
  const ctr = impressions > 0 ? (clicks / impressions) * 100 : 0;

  return { spend, impressions, clicks, leads, cpl, ctr };
}

const variantA = parseMetrics(metricsA);
const variantB = parseMetrics(metricsB);

// Расчёт статистической значимости (Z-test)
function calculateConfidence(leadsA, impressionsA, leadsB, impressionsB) {
  if (impressionsA < 100 || impressionsB < 100) return 0;

  const rateA = leadsA / impressionsA;
  const rateB = leadsB / impressionsB;
  const pooledRate = (leadsA + leadsB) / (impressionsA + impressionsB);

  if (pooledRate === 0 || pooledRate === 1) return 0;

  const se = Math.sqrt(pooledRate * (1 - pooledRate) * (1/impressionsA + 1/impressionsB));
  if (se === 0) return 0;

  const z = Math.abs(rateA - rateB) / se;

  // Упрощённое преобразование Z в confidence
  // z=1.96 -> 95%, z=2.58 -> 99%
  const confidence = Math.min(99.9, z * 38.5); // Аппроксимация
  return Math.max(0, Math.round(confidence * 10) / 10);
}

const confidence = calculateConfidence(
  variantA.leads, variantA.impressions,
  variantB.leads, variantB.impressions
);

// Определяем победителя
let winner = null;
let winnerReason = '';
let aiRecommendation = '';

const threshold = testData.auto_winner_threshold || 95;
const minSample = testData.min_sample_size || 1000;
const totalImpressions = variantA.impressions + variantB.impressions;

if (totalImpressions < minSample) {
  aiRecommendation = `Недостаточно данных. Собрано ${totalImpressions} из ${minSample} показов.`;
} else if (confidence >= threshold) {
  // Сравниваем по CPL
  if (variantA.cpl && variantB.cpl) {
    if (variantA.cpl < variantB.cpl) {
      winner = 'a';
      const improvement = ((variantB.cpl - variantA.cpl) / variantB.cpl * 100).toFixed(1);
      winnerReason = `CPL на ${improvement}% ниже`;
      aiRecommendation = `Variant A побеждает с confidence ${confidence}%. CPL: $${variantA.cpl.toFixed(2)} vs $${variantB.cpl.toFixed(2)}. Рекомендуем масштабировать A и остановить B.`;
    } else {
      winner = 'b';
      const improvement = ((variantA.cpl - variantB.cpl) / variantA.cpl * 100).toFixed(1);
      winnerReason = `CPL на ${improvement}% ниже`;
      aiRecommendation = `Variant B побеждает с confidence ${confidence}%. CPL: $${variantB.cpl.toFixed(2)} vs $${variantA.cpl.toFixed(2)}. Рекомендуем масштабировать B и остановить A.`;
    }
  } else if (variantA.leads > 0 || variantB.leads > 0) {
    // Если нет CPL, сравниваем по количеству лидов
    if (variantA.leads > variantB.leads) {
      winner = 'a';
      winnerReason = `Больше лидов: ${variantA.leads} vs ${variantB.leads}`;
    } else {
      winner = 'b';
      winnerReason = `Больше лидов: ${variantB.leads} vs ${variantA.leads}`;
    }
  }
} else {
  const neededConfidence = threshold - confidence;
  aiRecommendation = `Confidence ${confidence}% < ${threshold}%. Нужно ещё ~${neededConfidence.toFixed(0)}% для определения победителя. A: CPL $${variantA.cpl?.toFixed(2) || 'N/A'}, B: CPL $${variantB.cpl?.toFixed(2) || 'N/A'}`;
}

return {
  test_id: testData.test_id,
  test_name: testData.test_name,

  // Метрики A
  variant_a_spend: variantA.spend,
  variant_a_impressions: variantA.impressions,
  variant_a_clicks: variantA.clicks,
  variant_a_leads: variantA.leads,
  variant_a_cpl: variantA.cpl,
  variant_a_ctr: variantA.ctr,

  // Метрики B
  variant_b_spend: variantB.spend,
  variant_b_impressions: variantB.impressions,
  variant_b_clicks: variantB.clicks,
  variant_b_leads: variantB.leads,
  variant_b_cpl: variantB.cpl,
  variant_b_ctr: variantB.ctr,

  // Результаты анализа
  confidence_level: confidence,
  winner: winner,
  winner_reason: winnerReason,
  ai_recommendation: aiRecommendation,
  ai_updated_at: new Date().toISOString()
};
